import React from 'react';
import './Page.css';

const Privacy = () => {
  return (
    <main className="page">
      <div className="page-inner">
        <header className="page-hero">
          <h1>Privacy Policy</h1>
          <p className="muted">We are committed to protecting your privacy — this outlines how we collect and use information.</p>
        </header>

        <section className="page-card">
          <h3>Information Collection</h3>
          <p className="muted">We collect information you provide directly (for example, when creating an account) and information collected automatically (such as usage data).</p>

          <h3 style={{ marginTop: '1rem' }}>Use of Information</h3>
          <p className="muted">We use personal data to provide, maintain, and improve our services and to communicate with you.</p>
        </section>
      </div>
    </main>
  );
};

export default Privacy;
